function validate([root]) {
  if (root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  const values = root.filter(v => v !== null);
  if (values.length > 100) return 'The tree has at most 100 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 99)) return 'Each node value is an integer from 0 to 99.';
  return null;
}

