function isUnivalTree(root) {
  // Collect every value with a level-order walk and count the distinct ones.
  const seen = new Set();
  const queue = [root];
  for (let i = 0; i < queue.length; i++) {
    const node = queue[i];
    if (!node) continue;
    seen.add(node.val);
    queue.push(node.left, node.right);
  }
  return seen.size === 1;
}

