function generate(rand, size) {
  const n = size === 'large' ? 80 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 10);
  // Attach each new node to a free child slot; a high bias favours the newest slots and grows long branches.
  const bias = rand();
  const nodes = [{ val: 0, left: null, right: null }], slots = [[0, 'left'], [0, 'right']];
  for (let i = 1; i < n; i++) {
    const k = rand() < bias ? slots.length - 1 - Math.floor(rand() * Math.min(2, slots.length)) : Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    nodes.push({ val: 0, left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  const base = rand() < 0.2 ? (rand() < 0.5 ? 0 : 99) : Math.floor(rand() * 100);
  const other = () => (base + 1 + Math.floor(rand() * 99)) % 100;
  for (const node of nodes) node.val = base;
  const mode = rand();
  if (mode < 0.4) {
    // Leave the tree uni-valued.
  } else if (mode < 0.8) {
    // Exactly one node differs; prefer late (deep) nodes so a lazy check misses it.
    const index = rand() < 0.5 ? n - 1 - Math.floor(rand() * Math.min(3, n)) : Math.floor(rand() * n);
    nodes[index].val = other();
  } else {
    const alt = other();
    for (const node of nodes) if (rand() < 0.3) node.val = alt;
  }
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [], queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
